+        int w = W;
+        for (int i = n; i > 0 && w > 0; i--) {
+            if (dp[i][w] != dp[i - 1][w]) {
+                Item item = problem.items.get(i - 1);
+                selected.add(item.id);
+                w -= item.weight;
+            }
+        }
+
+        return new Solution(dp[n][W], selected);
     }
+}

